(2583048, 356193, 51538, '<td valign="top">Nice idea, well worth the effort you went to composing it. 8.</td>', 'Nice idea, well worth the effort you went to composing it. 8.', '2006-07-04 08:59:46.000000', NULL, 1),
(2583060, 356920, 51538, '<td valign="top">Nice lupins there.  A completely loopy place to find a sunflower though!  Like the colours and focus, very accurate.</td>', 'Nice lupins there.  A completely loopy place to find a sunflower though!  Like the colours and focus, very accurate.', '2006-07-04 09:02:34.000000', NULL, 1),
