(2607984, 355861, 37961, '<td valign="top">Underrated. This one has alot of soul. I love the background color and overall mood.</td>', 'Underrated. This one has alot of soul. I love the background color and overall mood.', '2006-07-10 17:43:24.000000', NULL, 0),
(2608002, 355865, 22543, '<td valign="top">ouch. i dunno what happened... i liked it</td>', 'ouch. i dunno what happened... i liked it', '2006-07-10 17:49:52.000000', NULL, 0),
