INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2618200, 357088, 57229, '<td valign="top">These things look almost organic - like they just grew there or something - no wonder you got the sub-5 rush...<br/> <br/>I actually think it''s an excellent picture. You could have called it ''the flower''s point of view'' (please don''t say <i>perspective</i>) as in: ''Hey, we''re not just here to fucking decorate'' etc...</td>', 'These things look almost organic - like they just grew there or something - no wonder you got the sub-5 rush... I actually think it''s an excellent picture. You could have called it ''the flower''s point of view'' (please don''t say perspective) as in: ''Hey, we''re not just here to fucking decorate'' etc...', '2006-07-13 09:20:15.000000', NULL, 0),
